class Solution:
    def waysToReachTarget(self, target: int, types: List[List[int]]) -> int:
        MOD = 10**9 + 7
        dp = [1] + [0] * target
        for cnt, marks in types:
            ndp = [0] * (target + 1)
            for j in range(target + 1):
                s = 0
                for c in range(min(cnt, j // marks) + 1):
                    s += dp[j - c * marks]
                ndp[j] = s % MOD
            dp = ndp
        return dp[target]

