class Solution {
public:
    int waysToReachTarget(int target, vector<vector<int>>& types) {
        const int MOD = 1e9 + 7;
        vector<long long> dp(target + 1, 0), ndp(target + 1);
        dp[0] = 1;
        for (auto& tp : types) {
            fill(ndp.begin(), ndp.end(), 0LL);
            int cnt = tp[0], marks = tp[1];
            for (int j = 0; j <= target; ++j)
                for (int c = 0; c <= cnt && c * marks <= j; ++c)
                    ndp[j] = (ndp[j] + dp[j - c * marks]) % MOD;
            dp.swap(ndp);
        }
        return dp[target];
    }
};

