class Solution:
    def waysToReachTarget(self, target: int, types: List[List[int]]) -> int:
        MOD = 10**9 + 7
        from functools import lru_cache
        @lru_cache(None)
        def go(i, rem):
            if i == len(types):
                return 1 if rem == 0 else 0
            cnt, marks = types[i]
            return sum(go(i + 1, rem - c * marks)
                       for c in range(cnt + 1) if c * marks <= rem) % MOD
        return go(0, target)

