class Solution {
    int n;
    vector<vector<int>> memo;
    vector<vector<int>>& tp;
    const int MOD = 1e9 + 7;
    int go(int i, int rem) {
        if (i == n) return rem == 0;
        int& r = memo[i][rem];
        if (r != -1) return r;
        long long s = 0;
        for (int c = 0; c <= tp[i][0] && (long long)c * tp[i][1] <= rem; ++c)
            s += go(i + 1, rem - c * tp[i][1]);
        return r = s % MOD;
    }
public:
    int waysToReachTarget(int target, vector<vector<int>>& types) {
        n = types.size(); tp = types;
        memo.assign(n, vector<int>(target + 1, -1));
        return go(0, target);
    }
};

