class Solution {
    Integer[][] memo;
    int[][] types;
    final int MOD = 1_000_000_007;
    int go(int i, int rem) {
        if (i == types.length) return rem == 0 ? 1 : 0;
        if (memo[i][rem] != null) return memo[i][rem];
        long s = 0;
        for (int c = 0; c <= types[i][0] && (long) c * types[i][1] <= rem; ++c)
            s += go(i + 1, rem - c * types[i][1]);
        return memo[i][rem] = (int) (s % MOD);
    }
    public int waysToReachTarget(int target, int[][] types) {
        this.types = types;
        memo = new Integer[types.length][target + 1];
        return go(0, target);
    }
}

