var waysToReachTarget = function(target, types) {
    const MOD = 1e9 + 7;
    const memo = new Map();
    function go(i, rem) {
        if (i === types.length) return rem === 0 ? 1 : 0;
        const key = i * 10001 + rem;
        if (memo.has(key)) return memo.get(key);
        const [cnt, marks] = types[i];
        let s = 0;
        for (let c = 0; c <= cnt && c * marks <= rem; ++c)
            s += go(i + 1, rem - c * marks);
        s %= MOD;
        memo.set(key, s);
        return s;
    }
    return go(0, target);
};
